import { auth } from "@/lib/auth";
import { NextResponse } from "next/server";

// ─────────────────────────────────────────────────────────────────────────────
// Drape Middleware — route protection via Auth.js v5
// ─────────────────────────────────────────────────────────────────────────────

// Routes that require authentication
const PROTECTED_PREFIXES = [
  "/dashboard",
  "/api/ai",
  "/api/orders",
  "/api/enquiries",
  "/api/notifications",
  "/api/profile",
];

// Routes that should redirect already-authenticated users away
const AUTH_ROUTES = ["/sign-in", "/sign-up"];

export default auth((req) => {
  const { nextUrl } = req;
  const isLoggedIn = !!req.auth;
  const pathname = nextUrl.pathname;

  const isProtected = PROTECTED_PREFIXES.some((prefix) =>
    pathname.startsWith(prefix)
  );
  const isAuthRoute = AUTH_ROUTES.some((route) =>
    pathname.startsWith(route)
  );

  // Redirect authenticated users away from sign-in / sign-up
  if (isAuthRoute && isLoggedIn) {
    return NextResponse.redirect(new URL("/dashboard/client", nextUrl));
  }

  // Redirect unauthenticated users to sign-in, preserving callbackUrl
  if (isProtected && !isLoggedIn) {
    const signInUrl = new URL("/sign-in", nextUrl);
    signInUrl.searchParams.set("callbackUrl", pathname);
    return NextResponse.redirect(signInUrl);
  }

  return NextResponse.next();
});

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - _next/static (static files)
     * - _next/image (image optimisation)
     * - favicon.ico, sitemap.xml, robots.txt
     * - public folder image assets
     */
    "/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)",
  ],
};
